WITH deduped AS (SELECT id, order_id, quantity, unit_price FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id, order_id ORDER BY unit_price DESC NULLS FIRST, id) AS dedup_rank FROM order_items) ranked WHERE dedup_rank = 1) SELECT CASE WHEN quantity >= 8 THEN 'LARGE' ELSE 'SMALL' END AS quantity_tier, CASE WHEN unit_price >= 380 THEN 'PREMIUM' ELSE 'STANDARD' END AS unit_price_tier, COUNT(DISTINCT id) AS distinct_ids, SUM(quantity) AS total_quantity, STDDEV_SAMP(unit_price) AS unit_price_stddev FROM deduped GROUP BY CASE WHEN quantity >= 8 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN unit_price >= 380 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING distinct_ids < 1000 ORDER BY distinct_ids DESC NULLS LAST
